$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$Root = 'C:\VocFlow'
$Runtime = Join-Path $Root 'runtime'
$ServerDir = Join-Path $Root 'server'
$DataDir = Join-Path $Root 'data'
$UpdateDir = Join-Path $DataDir 'updates'
$ConfigDir = Join-Path $Root 'config'
$LogDir = Join-Path $Root 'logs'
$TempDir = Join-Path $Root 'tmp'
@($Root,$Runtime,$ServerDir,$DataDir,$UpdateDir,$ConfigDir,$LogDir,$TempDir) | ForEach-Object { New-Item -ItemType Directory -Force -Path $_ | Out-Null }
$NodeExe = Join-Path $Runtime 'node.exe'
if (-not (Test-Path $NodeExe)) {
  $NodeDownload = Join-Path $TempDir 'node.exe.download'
  Invoke-WebRequest -UseBasicParsing -Uri 'https://nodejs.org/dist/latest-v22.x/win-x64/node.exe' -OutFile $NodeDownload -TimeoutSec 180
  Move-Item -Force -LiteralPath $NodeDownload -Destination $NodeExe
}
$CaddyExe = Join-Path $Runtime 'caddy.exe'
if (-not (Test-Path $CaddyExe)) {
  $CaddyZip = Join-Path $TempDir 'caddy.zip'
  Invoke-WebRequest -UseBasicParsing -Uri 'https://github.com/caddyserver/caddy/releases/download/v2.10.2/caddy_2.10.2_windows_amd64.zip' -OutFile $CaddyZip -TimeoutSec 180
  Expand-Archive -Force -LiteralPath $CaddyZip -DestinationPath $Runtime
  Remove-Item -Force -LiteralPath $CaddyZip
}
$ServerCode = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[IO.File]::WriteAllText((Join-Path $ServerDir 'cloud-server.cjs'), $ServerCode, $Utf8NoBom)
$ApiRunner = @(
  '$env:PORT = ''8787'''
  '$env:VOCFLOW_CLOUD_HOST = ''127.0.0.1'''
  '$env:VOCFLOW_PUBLIC_URL = ''https://api.vocflow.cc.cd'''
  '$env:VOCFLOW_CLOUD_DATA_DIR = ''C:\VocFlow\data'''
  '$env:VOCFLOW_UPDATE_DIR = ''C:\VocFlow\data\updates'''
  '& ''C:\VocFlow\runtime\node.exe'' ''C:\VocFlow\server\cloud-server.cjs'' *>> ''C:\VocFlow\logs\api.log'''
) -join [Environment]::NewLine
[IO.File]::WriteAllText((Join-Path $Runtime 'start-api.ps1'), $ApiRunner, $Utf8NoBom)
$CaddyRunner = @(
  '& ''C:\VocFlow\runtime\caddy.exe'' run --config ''C:\VocFlow\config\Caddyfile'' --adapter caddyfile *>> ''C:\VocFlow\logs\caddy.log'''
) -join [Environment]::NewLine
[IO.File]::WriteAllText((Join-Path $Runtime 'start-caddy.ps1'), $CaddyRunner, $Utf8NoBom)
$Caddyfile = @(
  'api.vocflow.cc.cd {'
  '    encode zstd gzip'
  '    reverse_proxy 127.0.0.1:8787'
  '}'
) -join [Environment]::NewLine
[IO.File]::WriteAllText((Join-Path $ConfigDir 'Caddyfile'), $Caddyfile, $Utf8NoBom)
foreach ($Rule in @(@{Name='VocFlow API HTTP';Port=80},@{Name='VocFlow API HTTPS';Port=443})) {
  $Existing = Get-NetFirewallRule -DisplayName $Rule.Name -ErrorAction SilentlyContinue
  if (-not $Existing) {
    New-NetFirewallRule -DisplayName $Rule.Name -Direction Inbound -Action Allow -Protocol TCP -LocalPort $Rule.Port -Profile Any | Out-Null
  }
}
function Register-VocFlowTask {
  param([string]$Name, [string]$ScriptPath)
  $Existing = Get-ScheduledTask -TaskName $Name -ErrorAction SilentlyContinue
  if ($Existing) {
    Stop-ScheduledTask -TaskName $Name -ErrorAction SilentlyContinue
    Unregister-ScheduledTask -TaskName $Name -Confirm:$false
  }
  $Action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $ScriptPath + '"')
  $Trigger = New-ScheduledTaskTrigger -AtStartup
  $Settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1)
  Register-ScheduledTask -TaskName $Name -Action $Action -Trigger $Trigger -Settings $Settings -User 'SYSTEM' -RunLevel Highest | Out-Null
}
Register-VocFlowTask -Name 'VocFlow API' -ScriptPath (Join-Path $Runtime 'start-api.ps1')
Register-VocFlowTask -Name 'VocFlow Caddy' -ScriptPath (Join-Path $Runtime 'start-caddy.ps1')
Start-ScheduledTask -TaskName 'VocFlow API'
$Health = $null
for ($i = 0; $i -lt 30; $i++) {
  Start-Sleep -Seconds 1
  try {
    $Health = Invoke-RestMethod -UseBasicParsing -Uri 'http://127.0.0.1:8787/health' -TimeoutSec 3
    break
  } catch {}
}
$NodeVersion = (& $NodeExe --version 2>&1 | Out-String).Trim()
$CaddyVersion = (& $CaddyExe version 2>&1 | Out-String).Trim()
$ApiTask = Get-ScheduledTask -TaskName 'VocFlow API' | Select-Object TaskName,State
[pscustomobject]@{
  Node = $NodeVersion
  Caddy = $CaddyVersion
  Health = $Health
  ApiTask = $ApiTask
  Listening = @(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object { $_.LocalPort -in 80,443,8787 } | Select-Object LocalAddress,LocalPort,OwningProcess)
} | ConvertTo-Json -Depth 6 -Compress